-- Verification Query
SELECT 
    (SELECT COUNT(*) FROM PoliceStation) AS PoliceStations,
    (SELECT COUNT(*) FROM Officer) AS Officers,
    (SELECT COUNT(*) FROM CrimeType) AS CrimeTypes,
    (SELECT COUNT(*) FROM Premises) AS Premises,
    (SELECT COUNT(*) FROM Weapon) AS Weapons,
    (SELECT COUNT(*) FROM CaseStatus) AS CaseStatuses,
    (SELECT COUNT(*) FROM Court) AS Courts,
    (SELECT COUNT(*) FROM FIR) AS Total_FIRs,
    (SELECT COUNT(*) FROM FIR_CrimeType) AS FIR_Crime_Links,
    (SELECT COUNT(*) FROM Victim) AS Total_Victims,
    (SELECT COUNT(*) FROM Accused) AS Total_Accused,
    (SELECT COUNT(*) FROM CourtCase) AS Total_CourtCases;
